CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715225217_InitialCreate') THEN
    CREATE TABLE "Parts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Category" text NOT NULL,
        "Brand" text NOT NULL,
        "Reference" text NOT NULL,
        "Minimum" integer NOT NULL,
        CONSTRAINT "PK_Parts" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715225217_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "LastName" text NOT NULL,
        "FirstName" text NOT NULL,
        "Function" text NOT NULL,
        "Email" text NOT NULL,
        "Login" text NOT NULL,
        "PasswordHash" text NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715225217_InitialCreate') THEN
    CREATE TABLE "Vehicles" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RegistrationOld" text,
        "RegistrationNew" text,
        "CustomIdentifier" text,
        "Brand" text NOT NULL,
        "Model" text NOT NULL,
        "Mileage" integer NOT NULL,
        CONSTRAINT "PK_Vehicles" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715225217_InitialCreate') THEN
    CREATE TABLE "StockEntries" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Quantity" integer NOT NULL,
        "UnitCost" numeric(10,2) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "PartId" integer NOT NULL,
        "UserId" integer NOT NULL,
        CONSTRAINT "PK_StockEntries" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StockEntries_Parts_PartId" FOREIGN KEY ("PartId") REFERENCES "Parts" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_StockEntries_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

