        CONSTRAINT "PK_Operations" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Operations_MetaOperations_MetaOperationId" FOREIGN KEY ("MetaOperationId") REFERENCES "MetaOperations" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_Operations_Vehicles_VehicleId" FOREIGN KEY ("VehicleId") REFERENCES "Vehicles" ("Id") ON DELETE CASCADE
